<?php
use PHPUnit\Framework\TestCase;

/** Supplied claims are consistency DATA only; no physical admission is claimed. */
final class SourcePolicyMinimumLaunchDataTest extends TestCase {
	protected function setUp():void {require_once dirname(__DIR__).'/scripts/manual/source-policy-minimum-launch-data.php';require_once __DIR__.'/support/source-policy-minimum-preflight-fixtures.php';}
	public function test_valid_synthetic_layout_binds_every_claim_without_authority() {
		$f=minimum_launch_fixture();$r=Alynt_Drime_Backups_Dashboard_Minimum_Launch_Data::inspect($f);$this->assertTrue($r['synthetic_consistent']);foreach(array('execution','load_authorized','filesystem_verified','platform_verified','native_qualified') as $key)$this->assertFalse($r[$key]);$this->assertMatchesRegularExpression('/\A[a-f0-9]{64}\z/',$r['manifest_sha256']);
		$f['files']['worker.php']=str_repeat('f',64);$other=Alynt_Drime_Backups_Dashboard_Minimum_Launch_Data::inspect($f);$this->assertNotSame($r['manifest_sha256'],$other['manifest_sha256']);$this->assertNotSame($r['source_sha256'],$other['source_sha256']);
	}
	/** @dataProvider layout_mutations */
	public function test_required_layout_dependency_and_environment_guards($case) {
		$f=minimum_launch_fixture();switch($case){case 'extra':$f['ready']=true;break;case 'relative':$f['root']='Temp/alynt-minimum-'.str_repeat('a',32);break;case 'traversal':$f['root']='C:/Temp/../alynt-minimum-'.str_repeat('a',32);break;case 'root-run':$f['run']=str_repeat('b',32);break;case 'platform-root':$f['root']='C:/Windows/alynt-minimum-'.$f['run'];break;case 'platform-source':$f['platform']['provenance']='self-hash';break;case 'system':$f['platform']['system']='C:/Users/System32';break;case 'build':$f['platform']['build']=array();break;case 'digest':$f['artifacts']['php_sha256']=str_repeat('0',64);break;case 'tree':$f['artifacts']['core_tree']=str_repeat('0',40);break;case 'pins':$f['artifacts']['source_pins']='12';break;case 'missing-role':unset($f['files']['php7.dll']);break;case 'extra-dll':$f['files']['extra.dll']=str_repeat('a',64);break;case 'role-case':$f['files']['PHP.exe']=$f['files']['php.exe'];unset($f['files']['php.exe']);break;case 'role-hash':$f['files']['php.exe']=str_repeat('0',64);break;case 'worker-type':$f['files']['worker.php']=new stdClass;break;case 'cwd':$f['cwd_entries']=array('php.ini');break;case 'path':$f['environment']['PATH'].=';C:/User';break;case 'ini':$f['environment']['PHPRC']='C:/User';break;case 'env-case':$f['environment']['Path']=$f['environment']['PATH'];break;case 'temp':$f['environment']['TMP']='C:/Temp';break;case 'unknown':$f['dependencies']['unknown.dll']='platform-profile';break;case 'lookalike':$f['dependencies']['imagehlp2.dll']=$f['dependencies']['imagehlp.dll'];unset($f['dependencies']['imagehlp.dll']);break;case 'missing-api':unset($f['dependencies']['api-ms-win-crt-runtime-l1-1-0.dll']);break;case 'crt-provenance':$f['dependencies']['vcruntime140.dll']='sha256-only';break;}
		$this->assertFalse(Alynt_Drime_Backups_Dashboard_Minimum_Launch_Data::inspect($f),$case);
	}
	public static function layout_mutations(){return array_map(function($v){return array($v);},array('extra','relative','traversal','root-run','platform-root','platform-source','system','build','digest','tree','pins','missing-role','extra-dll','role-case','role-hash','worker-type','cwd','path','ini','env-case','temp','unknown','lookalike','missing-api','crt-provenance'));}
	public function test_exact_runtime_facts_are_consistency_not_observation() {
		foreach(array('base','mysqli') as $stage){$facts=Alynt_Drime_Backups_Dashboard_Minimum_Launch_Data::runtime_template($stage,str_repeat('a',64),str_repeat('b',64));$this->assertTrue(Alynt_Drime_Backups_Dashboard_Minimum_Launch_Data::runtime_data($stage,$facts,str_repeat('a',64),str_repeat('b',64)));
			foreach(array('os'=>'Linux','php'=>'8.5.12','int_size'=>'8','zts'=>true,'sapi'=>'cgi','ini_loaded'=>'php.ini','ini_scanned'=>array(),'prepend'=>'x.php','append'=>'x.php','include_count'=>1,'source_sha256'=>str_repeat('c',64),'base_sha256'=>str_repeat('c',64),'mysqli_internal'=>'true','mysqlnd'=>'mysqlnd 8.5.12','mode_before'=>3,'mode_after'=>'0') as $key=>$value){$bad=$facts;$bad[$key]=$value;$this->assertFalse(Alynt_Drime_Backups_Dashboard_Minimum_Launch_Data::runtime_data($stage,$bad,str_repeat('a',64),str_repeat('b',64)),$stage.':'.$key);}
			$facts['extra']=true;$this->assertFalse(Alynt_Drime_Backups_Dashboard_Minimum_Launch_Data::runtime_data($stage,$facts,str_repeat('a',64),str_repeat('b',64)));
		}$this->assertFalse(Alynt_Drime_Backups_Dashboard_Minimum_Launch_Data::runtime_template('other',str_repeat('a',64),str_repeat('b',64)));
	}
	public function test_exact_module_set_and_all_fixed_application_roles_are_required() {
		$f=minimum_launch_fixture();foreach(array('base','mysqli') as $stage){$rows=minimum_modules_fixture($stage);$r=Alynt_Drime_Backups_Dashboard_Minimum_Launch_Data::module_data($stage,$f,$rows,array_reverse($rows));$this->assertSame(count($rows),$r['count']);$this->assertFalse($r['execution']);$this->assertFalse($r['platform_verified']);$this->assertFalse($r['native_qualified']);
			foreach(array('missing','extra','hash','path','origin','size','duplicate','alias') as $case){$bad=$rows;if('missing'===$case)array_pop($bad);elseif('extra'===$case)$bad[]=array('name'=>'other.dll','path'=>'C:/Windows/System32/other.dll','sha256'=>str_repeat('a',64),'size'=>1,'origin'=>'platform-profile');elseif('hash'===$case)$bad[0]['sha256']=str_repeat('0',64);elseif('path'===$case)$bad[0]['path']='C:/User/php.exe';elseif('origin'===$case)$bad[0]['origin']='platform-profile';elseif('size'===$case)$bad[0]['size']=33554433;elseif('duplicate'===$case)$bad[]=$rows[0];else $bad[0]['path']=str_replace('/runtime/','/runtime/../runtime/',$bad[0]['path']);$this->assertFalse(Alynt_Drime_Backups_Dashboard_Minimum_Launch_Data::module_data($stage,$f,$rows,$bad),$stage.':'.$case);}
			$bad=$rows;array_shift($bad);$this->assertFalse(Alynt_Drime_Backups_Dashboard_Minimum_Launch_Data::module_data($stage,$f,$bad,$bad),'Matching incomplete claims are not enough');
		}
		$rows=minimum_modules_fixture('mysqli');$this->assertFalse(Alynt_Drime_Backups_Dashboard_Minimum_Launch_Data::module_data('base',$f,$rows,$rows));
	}
	public function test_module_limits_provenance_claims_and_runtime_types_do_not_become_physical_evidence() {
		$c='Alynt_Drime_Backups_Dashboard_Minimum_Launch_Data';$f=minimum_launch_fixture();$rows=minimum_modules_fixture('base');$rows[]=array('name'=>'implementation.dll','path'=>'C:/Windows/System32/implementation.dll','sha256'=>str_repeat('d',64),'size'=>100,'origin'=>'platform-profile');$r=$c::module_data('base',$f,$rows,$rows);$this->assertTrue($r['synthetic_consistent']);$this->assertFalse($r['platform_verified'],'A forged label is still only supplied DATA');$this->assertFalse($r['execution']);
		$bad=$rows;$bad[4]['origin']='third-party';$this->assertFalse($c::module_data('base',$f,$bad,$bad));$this->assertFalse($c::module_data('base',$f,array_fill(0,129,$rows[0]),array_fill(0,129,$rows[0])));
		$huge=minimum_modules_fixture('base');for($i=0;$i<9;$i++)$huge[]=array('name'=>'system'.$i.'.dll','path'=>'C:/Windows/System32/system'.$i.'.dll','sha256'=>str_repeat('d',64),'size'=>33554432,'origin'=>'platform-profile');$this->assertFalse($c::module_data('base',$f,$huge,$huge));
		foreach(array('base','mysqli') as $stage){$facts=$c::runtime_template($stage,str_repeat('a',64),str_repeat('b',64));$facts['mysqli_internal']='base'===$stage;$this->assertFalse($c::runtime_data($stage,$facts,str_repeat('a',64),str_repeat('b',64)));}
		$facts=$c::runtime_template('mysqli',str_repeat('a',64),str_repeat('b',64));$facts['symbols']['mysqli_driver']['internal']=false;$this->assertFalse($c::runtime_data('mysqli',$facts,str_repeat('a',64),str_repeat('b',64)));$facts['symbols']['mysqli_driver']['internal']=true;$facts['symbols']['mysqli_get_client_info']['extension']='userland';$this->assertFalse($c::runtime_data('mysqli',$facts,str_repeat('a',64),str_repeat('b',64)));
	}
}
